INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b015c80d-4b28-4778-ba20-8adf2c7faa15', '1655cf08-16ec-44b5-b2f6-9b2c572c04e9', 0, 'Never coded, since it was never confirmed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1758acd-4bc8-4842-ad6e-bdce4c3f46a2', '1655cf08-16ec-44b5-b2f6-9b2c572c04e9', 1, 'Coded as if it existed, because the inpatient guideline for uncertain diagnoses (''probable,'' ''suspected,'' ''likely,'' ''questionable,'' ''possible,'' ''still to be ruled out'') directs coding the condition as if it were established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac840d6a-102b-4bc1-8271-80ff3a34a115', '1655cf08-16ec-44b5-b2f6-9b2c572c04e9', 2, 'Queried as mandatory before any code can be assigned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29daad08-6325-413c-96aa-4ca1ccb19782', '1655cf08-16ec-44b5-b2f6-9b2c572c04e9', 3, 'Coded only as a symptom, never the named condition');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
