INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d120e92-9bc2-4965-8d44-4972160807ca', '8874da51-fce9-4f69-b7b7-ee302bbd3d84', 0, 'Code the condition (appendicitis) as if confirmed, same as inpatient');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c9043b8-506a-4620-b085-a5daee6c06b3', '8874da51-fce9-4f69-b7b7-ee302bbd3d84', 1, 'Do not code the uncertain condition — code only the documented signs/symptoms prompting the visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3079424a-f69f-4019-8271-3a5ec1a8135b', '8874da51-fce9-4f69-b7b7-ee302bbd3d84', 2, 'Code both the uncertain condition and the symptoms together as co-principal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6a66ec9-d5c7-4c3e-9464-1eb384749db5', '8874da51-fce9-4f69-b7b7-ee302bbd3d84', 3, 'Query the provider before the encounter can be coded at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
