INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('291dcfb5-81d7-44b3-aa42-f1a87c743046', '8edeeb89-9439-467a-93de-9d339ba206ac', 0, 'The patient''s discharge disposition code only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aeba0aaf-80ba-4c78-9496-019f56ef4a6e', '8edeeb89-9439-467a-93de-9d339ba206ac', 1, 'MS-DRG assignment and associated reimbursement weight');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4c9dac7-1f16-4c7a-922b-31fc5b8728f9', '8edeeb89-9439-467a-93de-9d339ba206ac', 2, 'The sequence of the principal diagnosis only, never reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd2c7c50-090b-4ee2-a83b-695a0ca58705', '8edeeb89-9439-467a-93de-9d339ba206ac', 3, 'Only the POA indicator, not the DRG');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
