INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2fdc6505-0435-47a2-b191-37557972e61c', 'ce8ef9e7-163b-4722-b7da-b9a7ed8593ad', 0, 'Coding diabetes and the associated condition as two entirely unrelated, separately sequenced diagnoses with no combination logic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8290f83c-e21c-4137-8057-095a0ebd7736', 'ce8ef9e7-163b-4722-b7da-b9a7ed8593ad', 1, 'Using the combination-code structure in the diabetes mellitus codes, which link diabetes with its documented associated manifestation using ''with'' in the Alphabetic Index');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77c63aba-80fc-4178-8144-6f59d5777ba4', 'ce8ef9e7-163b-4722-b7da-b9a7ed8593ad', 2, 'Coding only the manifestation, never diabetes itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b2834f0-b7cf-4f1c-af62-5f351c0a5790', 'ce8ef9e7-163b-4722-b7da-b9a7ed8593ad', 3, 'Always sequencing the manifestation before diabetes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
