INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9600a06a-7eae-42d7-ba3c-f457f2de649c', 'cea0a5e5-805b-4f10-b2c6-324ee355da21', 0, 'Sequence in alphabetical order of the diagnosis descriptions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6a919fd-73bb-4429-89a4-83817395597a', 'cea0a5e5-805b-4f10-b2c6-324ee355da21', 1, 'Any one of them may be sequenced first, unless the circumstances of admission, diagnostic workup, and/or therapy provided indicate otherwise');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('406ca1f8-e311-4ab0-8c4e-72d45138549f', 'cea0a5e5-805b-4f10-b2c6-324ee355da21', 2, 'Always sequence the surgical condition first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a45ea187-b763-4b24-9262-07e733854a50', 'cea0a5e5-805b-4f10-b2c6-324ee355da21', 3, 'Sequence based on which condition was documented earliest in the chart');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
