INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6fcb4b1-02a0-4215-a80b-aba3897af4c3', '80dd3b1f-9211-47c6-9aa6-781d8b989155', 1, 'Taking out solid matter from a body part');
