INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4a4cd50-7538-4b45-8bd8-064aa9754807', '261db629-3223-40b7-b02b-1150e3c846be', 1, 'The approach actually completed — the open approach — is the one coded, not the approach that was attempted and abandoned');
