INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecd5f32f-06fb-44fc-8acf-8b3a05aceef4', 'e05a83b2-9b0b-459f-89be-760a496d938b', 0, 'The malignancy itself, always, regardless of the reason for the encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d9cba35-0a46-4b28-8df9-0e67c77c45f1', 'e05a83b2-9b0b-459f-89be-760a496d938b', 1, 'The appropriate code for the treatment encounter (e.g., encounter for chemotherapy), with the malignancy sequenced as a secondary diagnosis, per the neoplasm coding guideline');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b1477e3-862c-4bb8-a77f-187f24289985', 'e05a83b2-9b0b-459f-89be-760a496d938b', 2, 'Never codeable without a query');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('007dacf2-0e1c-4ab3-8c59-cd6a821ec265', 'e05a83b2-9b0b-459f-89be-760a496d938b', 3, 'The malignancy''s histology code only');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
