INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ceb8ade7-9687-4be2-8f9b-c8bd42f149fd', '08af2d67-e4d7-4f68-90f2-d4f63b213766', 0, 'Whether a condition is chronic or acute');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee68d19f-b66c-4112-91c9-7ceabcacc5e6', '08af2d67-e4d7-4f68-90f2-d4f63b213766', 1, 'The specification of right, left, or bilateral involvement of a paired organ or body part');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7be91d14-5569-46a9-87b8-a897e8f785df', '08af2d67-e4d7-4f68-90f2-d4f63b213766', 2, 'The severity level of a disease');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b35cb2c-f354-43ff-9d35-2908c6ca339e', '08af2d67-e4d7-4f68-90f2-d4f63b213766', 3, 'The timing of onset relative to admission');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
