INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be385612-0908-4016-aab6-f79b5f173b6f', '8b561641-f6ba-4f87-a9d5-c17e77fa9e24', 0, 'A single code covering the entire clinical picture');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('963080b9-cfcb-4ba1-b84e-c46b61ad6375', '8b561641-f6ba-4f87-a9d5-c17e77fa9e24', 1, 'The underlying systemic infection code sequenced first, followed by a code for severe sepsis (R65.2-), followed by codes for the specific acute organ dysfunction(s)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2b934c1-0119-44db-84d3-660e03ad573a', '8b561641-f6ba-4f87-a9d5-c17e77fa9e24', 2, 'Only the acute kidney injury code, since it is the most acute finding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21e4f67e-8c06-4562-baed-71ac975269fb', '8b561641-f6ba-4f87-a9d5-c17e77fa9e24', 3, 'Only a code for sepsis, with organ dysfunction never separately coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
