INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('623e246b-34c3-4cbb-9cf3-87a07de34154', 'a3d2fc20-8c1e-4f09-81e1-db1271e65b09', 0, 'Restriction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3a94c61-bd70-4a5c-b538-a340bb679793', 'a3d2fc20-8c1e-4f09-81e1-db1271e65b09', 1, 'Occlusion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eeebf6d-22bb-4d5b-898c-84ffef50610b', 'a3d2fc20-8c1e-4f09-81e1-db1271e65b09', 2, 'Dilation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a825bf9-d1ca-4b46-8cc5-7385534ffb00', 'a3d2fc20-8c1e-4f09-81e1-db1271e65b09', 3, 'Constriction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c5b60fa-7810-4028-9b8d-bc7cd2e61ced', 'cbd412ae-24ef-419a-a58c-bf0bf6920b87', 0, 'Occlusion completely closes an orifice or lumen; Restriction only partially narrows it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6d7a778-f413-4796-afb7-9ce020ae9c79', 'cbd412ae-24ef-419a-a58c-bf0bf6920b87', 1, 'They are interchangeable terms for the same root operation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59b500a4-d52b-4316-ba2e-eea69812b1f5', 'cbd412ae-24ef-419a-a58c-bf0bf6920b87', 2, 'Occlusion always requires a device; Restriction never does');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4027dbf7-98fb-4cf2-a811-1f90419fd83c', 'cbd412ae-24ef-419a-a58c-bf0bf6920b87', 3, 'Restriction is used only on the cardiovascular system');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7abc7d8b-41ad-40ea-9463-8b51170a50f8', 'c8a76014-861d-43a9-94cf-173be2f1f72d', 0, 'Only if the physician explicitly writes ''due to'' or ''secondary to''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('889e1362-ed74-47a4-9293-fc5ebbb93403', 'c8a76014-861d-43a9-94cf-173be2f1f72d', 1, 'Automatically, per the classification''s presumed causal relationship, unless the documentation clearly states the conditions are unrelated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('784359a3-4e51-4909-8421-3dba75f4f406', 'c8a76014-861d-43a9-94cf-173be2f1f72d', 2, 'Never — the two must always be linked explicitly by the provider');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f5e2e57-558f-4ff5-bd5f-672a948eba94', 'c8a76014-861d-43a9-94cf-173be2f1f72d', 3, 'Only in the outpatient setting');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
