INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ca30c79-87d1-47d7-8f90-184eac55868d', '8d316f10-3691-4a0c-92eb-42ea855c6b63', 0, 'Supplement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49e0f7c0-3cd1-48e1-bc47-1d705e1a6b7d', '8d316f10-3691-4a0c-92eb-42ea855c6b63', 1, 'Replacement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8572d04-b2aa-4a5a-8f6a-3510c8f37cb0', '8d316f10-3691-4a0c-92eb-42ea855c6b63', 2, 'Insertion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54d69296-0eda-4b3b-ab6d-e6f00b0edc81', '8d316f10-3691-4a0c-92eb-42ea855c6b63', 3, 'Transplantation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad88c381-9249-4d62-afc3-dff0bf40370d', 'f28dc650-852b-41ea-b57a-44bd9129167b', 0, 'Primary site is always sequenced first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6cb316dc-5b66-44bd-9602-31d84b248aa5', 'f28dc650-852b-41ea-b57a-44bd9129167b', 1, 'The secondary (metastatic) site is sequenced as principal/first-listed when treatment is directed at the secondary site, per the neoplasm guideline');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c62c9530-4930-48ac-b1b9-b454300dc97d', 'f28dc650-852b-41ea-b57a-44bd9129167b', 2, 'Only the primary site is ever coded once metastasis occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9dbc41f4-c700-423d-aed2-8b3b1c08ca65', 'f28dc650-852b-41ea-b57a-44bd9129167b', 3, 'Sequencing is determined solely by which site was diagnosed first, chronologically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57c83d4c-1ebc-4c00-b87d-115825981dd0', '1ad42fd5-e912-4070-aa47-aad7b6135c94', 0, 'Any adverse outcome occurs after any procedure, regardless of physician documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47a4febc-abd0-4682-aeaf-1cbb09c428c5', '1ad42fd5-e912-4070-aa47-aad7b6135c94', 1, 'The provider has documented a relationship between the condition and the procedure/care — a coder cannot assume a cause-and-effect relationship between a complication and surgical/medical care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67d6a8f3-01f7-4cbb-8eef-00d3dbfeb988', '1ad42fd5-e912-4070-aa47-aad7b6135c94', 2, 'The patient was on the operating table for more than 4 hours');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('186e2236-5eee-4d82-aa0c-2e28b0ad60bc', '1ad42fd5-e912-4070-aa47-aad7b6135c94', 3, 'It occurs strictly within 24 hours of the procedure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f1aff39-549a-475e-bbfd-1e6deecfaad3', '4b4c285f-00df-4961-996e-74cc1ab48fed', 0, 'Excision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0cb9a80-d844-4c55-bedd-64b72dac0832', '4b4c285f-00df-4961-996e-74cc1ab48fed', 1, 'Resection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62fa0abd-49b0-4eb6-ac60-3163f6afb3ab', '4b4c285f-00df-4961-996e-74cc1ab48fed', 2, 'Extirpation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b61c3c05-924e-48a8-a564-de1e675f5746', '4b4c285f-00df-4961-996e-74cc1ab48fed', 3, 'Fragmentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5fc1c14-ede7-4edb-8a4d-00f82b87c060', '33be2956-0c48-41a3-ae0d-bd42398b280e', 0, 'Code it as confirmed automatically, since the inpatient uncertain-diagnosis guideline always applies without exception');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('413c2750-bd1f-435c-bb82-5ffd91c268f5', '33be2956-0c48-41a3-ae0d-bd42398b280e', 1, 'Never code it and drop it from the record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18fa21a7-d1b0-46a5-baad-727dde1b25de', '33be2956-0c48-41a3-ae0d-bd42398b280e', 2, 'Query the provider for clarification when the documentation is ambiguous rather than assume, consistent with ethical coding standards that prohibit coding based on assumption when clarification is reasonably obtainable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc7fdbb5-e543-4968-bb8b-bdc541017316', '33be2956-0c48-41a3-ae0d-bd42398b280e', 3, 'Assign the least specific code available and move on');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5003a7ef-1c01-407b-b3ca-8b4b1dda50f6', '6dbd0de8-de6c-463f-8231-be3e54db23e4', 0, 'Only poisoning and adverse effects of drugs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b1b109e-ae42-4afc-a967-3f53a0ef6723', '6dbd0de8-de6c-463f-8231-be3e54db23e4', 1, 'Encounters for reasons other than a current illness/injury, such as factors influencing health status, aftercare, screening, or history of a condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5059c2f2-844d-4bcf-9f58-e4d31f3fa439', '6dbd0de8-de6c-463f-8231-be3e54db23e4', 2, 'Only injuries from external causes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2a8841f-2a2f-4898-8027-aca314f3100c', '6dbd0de8-de6c-463f-8231-be3e54db23e4', 3, 'Only laboratory abnormalities with no clinical significance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84039045-d754-4d8b-8775-e053bd5ddf79', '850d93dc-2105-4764-8e6d-9cc4a946799d', 0, 'The UTI code alone, since it is the origin of the infection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea5cfaef-f618-497d-9992-002e72ac4121', '850d93dc-2105-4764-8e6d-9cc4a946799d', 1, 'The underlying systemic infection (sepsis due to the UTI), sequenced first, followed by the code for severe sepsis and then septic shock, per the sepsis guideline''s sequencing hierarchy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('650cee53-ddd4-4f3f-9493-c19bd9e78390', '850d93dc-2105-4764-8e6d-9cc4a946799d', 2, 'Septic shock alone, since it is the most acute condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f094f620-6496-4e37-9880-164a3ebe66d6', '850d93dc-2105-4764-8e6d-9cc4a946799d', 3, 'The UTI and sepsis coded as unrelated, co-equal principal diagnoses');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d15e6d3b-c63e-48b0-9aff-63645b9656a5', '00189343-0aa4-4b71-84cb-58881c3b290a', 0, 'Acceptable documentation variance requiring no action');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d24188ba-7cd5-4cb6-a382-031df742d4d6', '00189343-0aa4-4b71-84cb-58881c3b290a', 1, 'Conflicting documentation that must be resolved before a laterality-specific code can be confidently assigned — typically via a provider query');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce7d3673-3944-48b4-8045-f4954df9a9e8', '00189343-0aa4-4b71-84cb-58881c3b290a', 2, 'A coder discretion issue where the coder should simply pick the more recent note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef05dab4-256a-4f18-a8e5-959b3222892f', '00189343-0aa4-4b71-84cb-58881c3b290a', 3, 'Something that should be resolved by defaulting to ''bilateral, unspecified''');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5240f5e-c33b-41d7-ab82-ecb9a695f44e', 'a69621b7-d104-4924-9968-739f34e1d9ff', 0, 'Anywhere in the patient''s lifetime medical history across all facilities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e45a9a26-e56a-4883-ad35-3bfbc111d4bf', 'a69621b7-d104-4924-9968-739f34e1d9ff', 1, 'Within the body of the health record for the encounter being coded, documented by a provider who is legally accountable for establishing the patient''s diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3fb232dd-25fc-4074-88b7-f2c5411ff20e', 'a69621b7-d104-4924-9968-739f34e1d9ff', 2, 'In the discharge summary exclusively, never elsewhere in the chart');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8cf8aa5-ddd7-4f42-b4d7-79eb429b7617', 'a69621b7-d104-4924-9968-739f34e1d9ff', 3, 'In the nursing notes exclusively');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('123ec2a8-f204-4e77-815a-ad4406e8c98b', '5b5d0874-07b3-428a-bec0-0a789b744c79', 0, 'Assuming a diagnosis is accurate simply because it appears in the coding summary sheet without cross-checking the record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dcf2a861-0007-44e7-840f-16cd45bc589a', '5b5d0874-07b3-428a-bec0-0a789b744c79', 1, 'Cross-referencing a diagnosis or procedure documented in one part of the record (e.g., the problem list) against supporting clinical evidence elsewhere in the record (labs, orders, provider notes) to confirm consistency');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12cf8460-d5a7-439d-9547-774eea0d9392', '5b5d0874-07b3-428a-bec0-0a789b744c79', 2, 'Coding directly from a diagnosis-related billing sheet prepared by non-clinical administrative staff with no chart review at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('518e20f0-a46c-442e-ae91-16bc7eb46d1f', '5b5d0874-07b3-428a-bec0-0a789b744c79', 3, 'Relying solely on the discharge summary''s ICD-10 code list without reading any clinical notes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08aea025-7c5e-4097-9edd-8c6bbc1ca7ea', '690239a3-1969-433c-aceb-8027020742f6', 0, 'Assign the most common subtype code as a default assumption');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eef91de8-1d9f-47e6-8cca-c467d0492cd5', '690239a3-1969-433c-aceb-8027020742f6', 1, 'Recognize that unspecified documentation limits the coder to an unspecified heart failure code, or query the provider if a more specific code is likely warranted and obtainable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed2cbf31-7d56-4e8c-8488-fe9a84de44d0', '690239a3-1969-433c-aceb-8027020742f6', 2, 'Never code heart failure at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8daf5619-af06-43bd-bf28-27ef24dad0fe', '690239a3-1969-433c-aceb-8027020742f6', 3, 'Code both systolic and diastolic heart failure to cover all possibilities');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ccd1f7c-5a02-4717-a4fc-dff19495e46d', '6a13a0ca-2312-4031-9c3a-e0c52520ea06', 0, 'The operative report clearly documents the approach, body part, and root operation performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63c30f88-d91e-4d7c-833d-4ac1a692cc1a', '6a13a0ca-2312-4031-9c3a-e0c52520ea06', 1, 'The operative report is missing entirely, and only a preoperative order for ''possible appendectomy'' exists in the chart, with no documentation of what was actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e269600-a328-4703-95a6-6e160a554541', '6a13a0ca-2312-4031-9c3a-e0c52520ea06', 2, 'The pathology report confirms a diagnosis already suspected preoperatively');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1598bed-3a98-4017-87cf-85cf30fd2895', '6a13a0ca-2312-4031-9c3a-e0c52520ea06', 3, 'The anesthesia record documents the type of anesthesia used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3cd3cf58-2f89-4338-83cd-a19e26192b7f', '4fdb1fc1-a58b-4a35-bfdf-7abfacd8869d', 0, 'Provider query compliance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('470f01e1-0451-4ccd-94e5-4507195f09ff', '4fdb1fc1-a58b-4a35-bfdf-7abfacd8869d', 1, 'Resolving conflicting documentation in the health record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df3fa256-f562-44f3-a823-bc661ee95559', '4fdb1fc1-a58b-4a35-bfdf-7abfacd8869d', 2, 'HITECH compliance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5cc0e9d-519f-4982-9950-bb212288546c', '4fdb1fc1-a58b-4a35-bfdf-7abfacd8869d', 3, 'Encoder software configuration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4ee1a1a-55e2-489f-9045-df0982ea4f64', '531959d6-6d30-456f-a477-41d3b52aa3db', 0, 'The billing department''s internal notes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61ce8bd1-8dcf-4d95-9d02-e197ae30fde9', '531959d6-6d30-456f-a477-41d3b52aa3db', 1, 'Clinical documentation clearly establishing the timing of onset relative to the inpatient admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('edca5c7a-7a09-4afb-8e6e-2680ea11e163', '531959d6-6d30-456f-a477-41d3b52aa3db', 2, 'The patient''s verbal report to registration staff only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a233d3f-323a-4231-8556-457500228bd6', '531959d6-6d30-456f-a477-41d3b52aa3db', 3, 'The length of stay alone');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69bc51f1-3e90-438c-be3b-16597c02cd48', '695e0db2-f8ff-445e-bb07-ff28236fd02d', 0, 'Code it anyway since it''s on the summary sheet');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbebafa8-bb7b-42f4-968c-03bb47de98ea', '695e0db2-f8ff-445e-bb07-ff28236fd02d', 1, 'Do not assign a code based solely on a summary sheet entry unsupported by documentation elsewhere in the record — verify against the full record or query');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a649958c-5f3a-490c-afb8-1728159c00ca', '695e0db2-f8ff-445e-bb07-ff28236fd02d', 2, 'Delete the summary sheet');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af906e83-a07f-45de-88b4-05a017f1be80', '695e0db2-f8ff-445e-bb07-ff28236fd02d', 3, 'Assign the code but flag it as ''unconfirmed'' in the billing system, without further follow-up');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29375357-4b7a-4336-9c2a-5466f60775df', '703991f9-bd56-4bf6-a241-8fc322f78bac', 0, 'Only use documentation from the most senior physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('599e66b3-d265-4bb1-a05d-d9ab5039a36c', '703991f9-bd56-4bf6-a241-8fc322f78bac', 1, 'Synthesize accurate coding from the complete record across all legitimate provider documentation, since UHDDS reporting is based on the record as a whole, not a single provider''s note in isolation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('588c46a3-f1ad-400f-a911-89af057ef526', '703991f9-bd56-4bf6-a241-8fc322f78bac', 2, 'Query both physicians regardless of whether the picture is already clear from combined documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3862d164-8319-4da8-94db-5c8411983a3d', '703991f9-bd56-4bf6-a241-8fc322f78bac', 3, 'Refuse to code until a single physician documents the entire picture in one note');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73b93b31-a0d0-446d-bafd-4883e8aac7b9', '1d2c2d69-aa86-444d-b342-c1dd8a06d43c', 0, 'No specific documentation standard applies to CC/MCC-designated diagnoses');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0180999d-3a95-4ba3-b48f-17a6758bebea', '1d2c2d69-aa86-444d-b342-c1dd8a06d43c', 1, 'The condition must be clearly and consistently documented as clinically significant/being treated, monitored, or evaluated during the stay — not merely listed once without clinical substantiation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52a7761e-9167-4de9-a893-565c1c9db897', '1d2c2d69-aa86-444d-b342-c1dd8a06d43c', 2, 'Any mention anywhere in the chart is automatically sufficient regardless of clinical substantiation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e4dce31-950a-4b45-bb35-4124c5ab4cd1', '1d2c2d69-aa86-444d-b342-c1dd8a06d43c', 3, 'CC/MCC diagnoses require documentation only in the discharge summary');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d31038a2-18b6-4325-b4cc-bb8c95abd17e', '6e3ca389-8316-4c02-a340-c932e9563e50', 0, 'A non-issue; any mention of malnutrition supports the most severe code available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ce2002e-f20f-4c49-a48b-a4a75d57c6dd', '6e3ca389-8316-4c02-a340-c932e9563e50', 1, 'A gap requiring either additional supporting clinical indicators in the record or a compliant query to establish/confirm the severity before assigning a specific severity code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d781288e-d16d-4c3f-917b-7a567f3f5676', '6e3ca389-8316-4c02-a340-c932e9563e50', 2, 'Something the CDI specialist alone can resolve by picking the code without coder or provider involvement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35b236e1-bdee-4356-bb2c-19793d84c993', '6e3ca389-8316-4c02-a340-c932e9563e50', 3, 'Irrelevant to DRG assignment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62ae6a6e-a611-4dd1-8002-de338aeb0564', 'cd7d92ba-4303-4b84-b9ff-71b6a68de47e', 0, 'Confirming a secondary diagnosis coded for CC/MCC purposes has documented evidence of clinical evaluation, treatment, or monitoring somewhere in the actual chart, not just an entry on an unsupported list');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1114ea3e-0c00-443e-b95e-8706308341f8', 'cd7d92ba-4303-4b84-b9ff-71b6a68de47e', 1, 'Assuming documentation exists because the diagnosis appears plausible clinically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee8627ca-a4e1-4be3-8fbc-b5a9b90e16e5', 'cd7d92ba-4303-4b84-b9ff-71b6a68de47e', 2, 'Skipping verification for diagnoses that don''t affect DRG weight');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e70ef18c-f3a8-4b6d-8627-895411f7fd80', 'cd7d92ba-4303-4b84-b9ff-71b6a68de47e', 3, 'Verifying only diagnoses explicitly requested by the billing department');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34c6ad9a-0eea-454a-b61c-67125cb90c9c', 'e4da2a69-8d28-4e76-a343-7118dc620161', 0, 'These are the same event and only the discharge summary''s ''history of MI'' should be coded, as a personal history code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b1ed331-1f91-49c3-a6be-f9b679702d11', 'e4da2a69-8d28-4e76-a343-7118dc620161', 1, 'These likely represent two different clinical facts (an old, resolved MI in history, and a new acute MI this admission) requiring careful review — not automatic collapsing into one code — and a query if the timeline is genuinely unclear');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97589e48-d456-440d-9188-439550c35be6', 'e4da2a69-8d28-4e76-a343-7118dc620161', 2, 'The discrepancy is a HIPAA violation requiring reporting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0b3dce5-0003-4144-ae76-fcf929c37af0', 'e4da2a69-8d28-4e76-a343-7118dc620161', 3, 'The two notes must always be reconciled by deleting one of them from the chart');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f049547-550c-43bd-9762-9a05c0640c60', '6af54dd6-d015-4eea-a05f-d375c7de1fda', 0, 'Co-signed by a family member');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ca9db3b-4566-4f7d-970f-b7fcd0d4483f', '6af54dd6-d015-4eea-a05f-d375c7de1fda', 1, 'Authenticated (signed) by the performing provider and consistent with other record entries (anesthesia record, pathology, nursing notes) describing the same episode of care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fd8cb81-67d4-4d6b-88eb-5160e8784441', '6af54dd6-d015-4eea-a05f-d375c7de1fda', 2, 'Written exclusively in template/checkbox format with no free text');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d53a2bb0-9713-49f8-8e0b-47f4f3f81658', '6af54dd6-d015-4eea-a05f-d375c7de1fda', 3, 'Filed within 30 days of discharge, with no other requirement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e00e096-4742-4969-97c5-49dd31f7a22b', 'abf363c7-10ed-46b3-b59d-98d68ccf5531', 0, 'A wound is documented as ''stage 2 pressure ulcer'' by wound care on day 3 of the stay, with no ED or admission documentation addressing skin integument at all, making it unclear whether it existed at admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13914d40-3f09-47c8-942a-dcedce6dec39', 'abf363c7-10ed-46b3-b59d-98d68ccf5531', 1, 'A lab value is slightly abnormal but clinically insignificant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60f9fe22-9393-49e7-b7de-cd01d297bb50', 'abf363c7-10ed-46b3-b59d-98d68ccf5531', 2, 'A medication list is missing a dosage strength');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a2bda63-2814-4579-b51d-0d5b7a942c44', 'abf363c7-10ed-46b3-b59d-98d68ccf5531', 3, 'A discharge instruction sheet has a typo in the follow-up date');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6bd8d29-3e3d-428a-8a7f-a01f5503faf4', 'c7f6883f-b051-4640-933e-335869d967df', 0, 'Assume the laparoscopic approach was used because that''s what was originally planned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa29bbde-35ae-4b40-8e6e-d1ea53a66781', 'c7f6883f-b051-4640-933e-335869d967df', 1, 'Read the full body of the operative note narrative (not just a summary line) to determine the approach actually completed, since ICD-10-PCS coding is based on what was actually performed, not what was planned or a possibly-incomplete summary line');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b58bc2e-a21f-4926-abdf-aea605e0e7f8', 'c7f6883f-b051-4640-933e-335869d967df', 2, 'Query the surgeon before reading the rest of the note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db4bd8ea-fa90-4dfc-8ae9-585539b77492', 'c7f6883f-b051-4640-933e-335869d967df', 3, 'Default to ''open'' any time conversion is mentioned anywhere, without reading further');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83528806-6f8e-457f-bd9f-a9beddb1c5d7', 'a3d83877-0335-49d9-b2fa-7ef363f9cd89', 0, 'Coding it automatically from the nursing note alone, since nursing documentation is always sufficient to establish a diagnosis for coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02b15f0b-99d8-47cb-acd9-195294121795', 'a3d83877-0335-49d9-b2fa-7ef363f9cd89', 1, 'Recognizing that most diagnoses require provider (not nursing-alone) documentation to be codeable, and either locating physician documentation elsewhere in the record or querying the provider to confirm/establish the diagnosis, consistent with the general principle that a diagnosis must be documented by someone legally accountable for it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2482f0c-d0c4-4668-bf21-23812a2eab52', 'a3d83877-0335-49d9-b2fa-7ef363f9cd89', 2, 'Ignoring the nursing note entirely with no further action');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e117f892-4241-4bb2-a742-3c8fe9d16dbf', 'a3d83877-0335-49d9-b2fa-7ef363f9cd89', 3, 'Coding it as present on admission automatically without provider confirmation of the diagnosis itself');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c6ebdc6-7c55-49ba-844a-dfe9c13fffb3', 'bacd653e-cc5f-441d-873c-a4f718e8f1a1', 0, 'Coders should always use the original, unamended version of a note, ignoring any later corrections');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6fc929b-4509-41fe-b2c3-b21202e00ae7', 'bacd653e-cc5f-441d-873c-a4f718e8f1a1', 1, 'Coders should use the most current, properly authenticated version of the documentation (including compliant amendments/addenda), since the record''s amendment/correction process is designed to reflect the accurate clinical picture');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fdd148d1-85b3-4178-97c3-98af33fd262e', 'bacd653e-cc5f-441d-873c-a4f718e8f1a1', 2, 'Amended notes can never be used for coding under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bc1510f-dc86-465e-baaa-32dbdb57b21b', 'bacd653e-cc5f-441d-873c-a4f718e8f1a1', 3, 'Only amendments made within 24 hours of the original note are valid for coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa993e01-b86e-4a75-af58-f57e851a59da', '057f6a00-6f7b-4cb7-97bf-4eb77a550a80', 0, 'The coder picking whichever diagnosis appears first chronologically in the chart');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd4f6086-18f1-4fab-b0c0-545eeff1e4b3', '057f6a00-6f7b-4cb7-97bf-4eb77a550a80', 1, 'Recognizing this as unresolved conflicting documentation regarding the actual clinical diagnosis — appropriately addressed through further chart review for a resolving note or a compliant, non-leading query to the responsible provider(s), not an unsupported coder guess');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68e9e694-6db9-4aa3-b38d-6c0aefc5e7d5', '057f6a00-6f7b-4cb7-97bf-4eb77a550a80', 2, 'Coding both conditions as co-principal automatically with no further review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0593e483-f19d-48ca-a6db-57bc69aedea2', '057f6a00-6f7b-4cb7-97bf-4eb77a550a80', 3, 'Defaulting to the ED note only, since it was documented first');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('65ea2a45-68ed-4ad9-8eae-72b35f6e7d31', 'b2acfbe0-31db-40de-8095-5ebd3cc2d0c9', 0, 'Ignore the discrepancy since disposition doesn''t affect anything coding-related');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f211afe6-5727-4444-a7e4-69661cd0fb0f', 'b2acfbe0-31db-40de-8095-5ebd3cc2d0c9', 1, 'Resolve the discrepancy against the health record before finalizing abstracted data, since an inaccurate disposition can both misstate UHDDS data and trigger an incorrect post-acute-transfer payment adjustment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('857a6a45-4262-4752-a9b1-9aa023720aaf', 'b2acfbe0-31db-40de-8095-5ebd3cc2d0c9', 2, 'Always default to whichever disposition results in higher reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('153dbf2a-7e02-4b2a-b880-1a91dee832c5', 'b2acfbe0-31db-40de-8095-5ebd3cc2d0c9', 3, 'Report both dispositions simultaneously on the claim');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b151a68-8a30-4b52-9ad2-61158688897e', '56ce4eaf-46ce-49c0-96bf-0509b14707bb', 0, 'It suggests only one specific diagnosis the coder believes is correct, worded so the provider need only agree');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c3c3c8c-1845-4121-80f3-0d00f2fc65c9', '56ce4eaf-46ce-49c0-96bf-0509b14707bb', 1, 'It is non-leading — presenting clinical indicators and offering multiple reasonable clinical options (including ''other,'' ''clinically undetermined,'' or ''not clinically significant'') rather than suggesting a predetermined answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('923f5d61-7b80-483e-918d-fe59ae6fd23e', '56ce4eaf-46ce-49c0-96bf-0509b14707bb', 2, 'It is submitted verbally only, with no written or auditable trail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82e33db8-cb8b-4ca0-9091-d45ebc574500', '56ce4eaf-46ce-49c0-96bf-0509b14707bb', 3, 'It is generated automatically by encoder software without any clinical indicator review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4acdc50d-599f-4e2a-8d1f-b2caaca19f13', 'f156a414-44a1-4177-ad6e-5fb13a459307', 0, 'It is fully compliant and requires no changes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8282ead0-206e-4d8b-a843-1068126bfe65', 'f156a414-44a1-4177-ad6e-5fb13a459307', 1, 'It suggests the specific diagnosis to be confirmed rather than presenting clinical indicators and asking an open, non-leading question about their clinical significance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59af1c8c-1746-48e2-bc7e-b470134458d3', 'f156a414-44a1-4177-ad6e-5fb13a459307', 2, 'It uses too much clinical detail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a5f7b57-fc0c-4888-b97b-e29101aa31df', 'f156a414-44a1-4177-ad6e-5fb13a459307', 3, 'It should have been sent to a different department');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('494ccc1e-5355-4973-9350-d539cb414fff', '50b5848c-7a78-42e4-8766-211e12b3f04f', 0, '''The patient''s creatinine rose from a baseline of 0.9 to 2.1 during this admission. Please clarify if this represents acute kidney injury, a chronic process, another etiology, or is not clinically significant.''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a3ff324-cfb7-491c-9328-f798a82c3264', '50b5848c-7a78-42e4-8766-211e12b3f04f', 1, '''Please diagnose the patient with acute kidney injury based on the creatinine values.''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0fc36c97-8917-4a72-9442-948286937ea1', '50b5848c-7a78-42e4-8766-211e12b3f04f', 2, '''Do you agree the patient has acute kidney injury? Yes/No.''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('881f766e-fc73-44cd-9c52-dbe14457d94c', '50b5848c-7a78-42e4-8766-211e12b3f04f', 3, '''Please just add AKI to the problem list.''');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a57f3812-226c-4d80-96ee-a72e40ad1138', '36116927-cafd-4c72-8dbb-3e47440ad726', 0, 'Looking for any documentation gap regardless of whether it affects code assignment, severity, or compliance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8131c50a-8b14-42b8-95f2-2b4751ac6331', '36116927-cafd-4c72-8dbb-3e47440ad726', 1, 'Recognizing clinical indicators, treatments, or test results in the record that are not matched by a specific enough diagnosis statement, an unaddressed conflict, or missing linkage needed for accurate and complete coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67dbdc41-1b93-4104-9c73-785f603effd8', '36116927-cafd-4c72-8dbb-3e47440ad726', 2, 'Querying every chart as a routine matter regardless of documentation quality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa97d442-cbdb-40bd-931f-f690903feae1', '36116927-cafd-4c72-8dbb-3e47440ad726', 3, 'Only querying when a physician requests it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('473b23e4-e21f-43e1-a250-20e14511ed21', '108617df-c3bb-40a7-8b3e-f79f0a8f3b28', 0, 'Only the single diagnosis the coder or CDI specialist suspects is correct');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad3c43d4-86ef-484f-9f29-8122746e884d', '108617df-c3bb-40a7-8b3e-f79f0a8f3b28', 1, '''Clinically undetermined'' or ''unable to determine,'' when genuinely clinically appropriate, alongside other reasonable options');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdf1ab19-f140-4413-83bb-8ebd1552d61a', '108617df-c3bb-40a7-8b3e-f79f0a8f3b28', 2, 'No answer options at all — an open free-text-only format is prohibited under all circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae1d617c-546a-474e-b4c0-8378877e037e', '108617df-c3bb-40a7-8b3e-f79f0a8f3b28', 3, 'A pre-checked default answer that the provider must actively uncheck to disagree');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6035ec5-dca8-44f8-936f-009b20f43424', 'fd0206fd-a3d0-4a26-aacf-7f1a96cdcd0a', 0, 'Never — all queries must always be written, with no exceptions under any organization''s policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae4e52ff-b2b0-4f81-92b9-9adf74196cf9', 'fd0206fd-a3d0-4a26-aacf-7f1a96cdcd0a', 1, 'They are subsequently documented in the health record per organizational policy, since queries (verbal or written) should generally leave an auditable record of what was asked and answered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0fea7702-ce7f-499c-92ec-53b6f088ae3c', 'fd0206fd-a3d0-4a26-aacf-7f1a96cdcd0a', 2, 'They occur informally in a hallway conversation with no need for any record at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ad1f78b-db2b-4dc3-9382-431f2b7c0f4c', 'fd0206fd-a3d0-4a26-aacf-7f1a96cdcd0a', 3, 'The coder simply remembers the conversation without documenting it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32dc60a2-8ab0-4802-a884-9f746fda46ea', '1302b9ee-afde-4705-a616-96c4b061028e', 0, '''Based on the elevated white count, fever, and positive blood culture, please clarify whether the patient has sepsis, a localized infection, or another process.''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf720bae-e97f-4be7-92aa-f1ee22c76795', '1302b9ee-afde-4705-a616-96c4b061028e', 1, '''Please confirm the patient has sepsis so the correct DRG can be assigned.''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('628e0e9d-4067-451a-b019-a0b39a5249ea', '1302b9ee-afde-4705-a616-96c4b061028e', 2, '''The chart notes possible pneumonia with no further documentation — can you clarify the final diagnosis?''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6c02d7d-c233-4e7f-a050-e7797fcb0a32', '1302b9ee-afde-4705-a616-96c4b061028e', 3, '''Please clarify whether the documented pressure ulcer was present on admission or developed during this stay.''');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8781d666-0955-41a9-a576-a07c73f00bb8', '63ef0f7e-f057-4b1b-b6f2-5d76d786cc6e', 0, 'Queries have no bearing on code accuracy or compliance risk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09514ea2-c9c0-464a-806b-c09f8b925fc9', '63ef0f7e-f057-4b1b-b6f2-5d76d786cc6e', 1, 'Improperly leading queries can result in inaccurate code assignment, inflated reimbursement, and potential compliance/fraud exposure for the facility and the coding professional');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b8cf642-de47-4edd-91ca-a1f7f147bb02', '63ef0f7e-f057-4b1b-b6f2-5d76d786cc6e', 2, 'Query compliance is solely the CDI department''s responsibility, never the coder''s');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86acd207-2b9e-4eb8-9d9a-ca39482a59f3', '63ef0f7e-f057-4b1b-b6f2-5d76d786cc6e', 3, 'Only outpatient queries carry compliance risk');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('541252e7-e75d-4670-ad69-9c6a100bbce0', 'fdfb2293-b0f9-4b99-aa1a-d780d6ed93ab', 0, 'A stable, chronic condition clearly documented and consistently monitored with no new clinical significance during this stay');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34939af2-61d5-470b-887e-4f39fab7820b', 'fdfb2293-b0f9-4b99-aa1a-d780d6ed93ab', 1, 'Abnormal lab/vital sign trends (e.g., rising lactate, hypotension) suggestive of a clinically significant condition (e.g., sepsis, shock) that is not yet specifically diagnosed anywhere in the documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('211223f6-0905-43a7-b022-7ee74412335a', 'fdfb2293-b0f9-4b99-aa1a-d780d6ed93ab', 2, 'A well-documented, fully specified principal diagnosis with clear supporting evidence');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70c0ec0c-e87e-4766-a515-1c09f3352a2f', 'fdfb2293-b0f9-4b99-aa1a-d780d6ed93ab', 3, 'Routine post-operative vital sign monitoring with no abnormal findings');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('478f2253-a510-4eac-ba19-ee861ea540df', 'a24c6a1a-a46c-4cc5-9298-dd4397e7f58e', 0, 'Never permitted under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a7e0233-2110-420e-8e85-41331ed092b8', 'a24c6a1a-a46c-4cc5-9298-dd4397e7f58e', 1, 'Generally permissible under most organizational query policies, provided it remains non-leading and is based on clinical indicators already documented in the record — retrospective queries are common practice, subject to the same compliance standards as concurrent queries');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec238d24-269f-499a-b10e-3cbe3658cc55', 'a24c6a1a-a46c-4cc5-9298-dd4397e7f58e', 2, 'Only permitted if the diagnosis being asked about would lower reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9882a0ae-5b9e-4c2a-984f-1e1063186145', 'a24c6a1a-a46c-4cc5-9298-dd4397e7f58e', 3, 'Automatically considered leading regardless of its wording');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53d74385-7064-41be-9534-616ec3e05be0', 'a9cb0c68-f1da-4739-ad6b-959d7500d04c', 0, 'Technical safeguards for electronic systems only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd4dbef5-c543-4bf2-a149-d5ee0072296d', 'a9cb0c68-f1da-4739-ad6b-959d7500d04c', 1, 'The use and disclosure of individually identifiable health information (protected health information, PHI) by covered entities and business associates');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b23a078-752d-46dd-909d-c51a3ad51b6b', 'a9cb0c68-f1da-4739-ad6b-959d7500d04c', 2, 'Only paper-based medical records, not electronic records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('178be01e-af57-497c-a2b8-b71155e8f534', 'a9cb0c68-f1da-4739-ad6b-959d7500d04c', 3, 'Only billing and claims data, not clinical documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7ffcdfc-7514-4efb-a05f-331f94fe20fc', '23bb3fab-be82-4ceb-8863-8f48cbd2dbd5', 0, 'The Security Rule addresses only paper records; the Privacy Rule addresses only electronic records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4878eada-d9f9-492a-bda2-f087a900dc88', '23bb3fab-be82-4ceb-8863-8f48cbd2dbd5', 1, 'The Security Rule establishes administrative, physical, and technical safeguards specifically for electronic PHI (ePHI); the Privacy Rule governs PHI use/disclosure in any form');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('652a72d1-f2d1-4a61-9d29-82c32ecb6a0e', '23bb3fab-be82-4ceb-8863-8f48cbd2dbd5', 2, 'They are the same rule under different names');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1214135f-1b5e-43ad-9259-a64bb6de8d8e', '23bb3fab-be82-4ceb-8863-8f48cbd2dbd5', 3, 'The Security Rule applies only to health plans, never to providers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09d6b207-8ad4-4271-8886-149eb1600481', 'ce41a10e-3528-4842-8461-1ab8b19657ef', 0, 'A billing code used only for outpatient claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d85777be-29d8-4be2-a6ec-ae98e2975f3a', 'ce41a10e-3528-4842-8461-1ab8b19657ef', 1, 'A measure, often derived from administrative/claims data (including ICD-10-CM/PCS codes and POA indicators), used to screen for potentially preventable complications or adverse events occurring during hospitalization');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63fe10cd-0141-49b3-a153-1febdc0ca082', 'ce41a10e-3528-4842-8461-1ab8b19657ef', 2, 'A type of provider license renewal requirement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8623879a-5ecd-48c6-b9d4-e4454e30a417', 'ce41a10e-3528-4842-8461-1ab8b19657ef', 3, 'A patient satisfaction survey score');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53e9c15f-c8be-4497-b8ae-fa9c108d33aa', '269bf9f2-8448-4c7b-8e78-fa4f953d0981', 0, 'Was present on admission and unrelated to hospital care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2695ceb0-d1f3-4b3d-ac42-74a2621e3ffb', '269bf9f2-8448-4c7b-8e78-fa4f953d0981', 1, 'Was not present on admission (POA = ''N'') and meets CMS criteria as reasonably preventable through application of evidence-based guidelines, potentially affecting payment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6297fe1f-4bd6-41db-98f0-2e79cbe00346', '269bf9f2-8448-4c7b-8e78-fa4f953d0981', 2, 'Is always fatal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8a78e0a-bc15-4a22-afc0-14ba3a907967', '269bf9f2-8448-4c7b-8e78-fa4f953d0981', 3, 'Only applies to conditions acquired during outpatient surgery');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c024861-0d96-40dc-ab6f-17cdded9d573', '2cc0f461-b78f-4ceb-b160-b36cddfd18c2', 0, 'Comply, since supervisors have final authority over all coding decisions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55a888ba-1c27-4dd8-9f0d-956845356fa3', '2cc0f461-b78f-4ceb-b160-b36cddfd18c2', 1, 'Decline to assign a code unsupported by documentation and escalate through appropriate compliance channels, since coding professionals are ethically obligated to code only what is supported by the health record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cab478aa-2b52-4547-a007-24b8a76a7631', '2cc0f461-b78f-4ceb-b160-b36cddfd18c2', 2, 'Assign the code but tell no one');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c1051f1-a1dd-4364-b969-c6c33b48ecb5', '2cc0f461-b78f-4ceb-b160-b36cddfd18c2', 3, 'Resign immediately without reporting the issue');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab791192-d04f-432e-8cf9-d1b7d4c44ebe', '8a009f7e-1654-4434-8f36-732bb7c55f89', 0, 'Following a facility''s internal billing preferences over the standardized UHDDS data set definitions whenever there''s a conflict');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a12cb2fb-ff1a-4cdd-adf0-df5be58b0cb8', '8a009f7e-1654-4434-8f36-732bb7c55f89', 1, 'Applying the standardized minimum data set definitions (e.g., principal diagnosis, other diagnoses, principal procedure) consistently, as UHDDS is the federally recognized uniform data set for inpatient discharge data reporting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c1585ce-ce6a-4860-8889-ce58cc7d9c5f', '8a009f7e-1654-4434-8f36-732bb7c55f89', 2, 'Reporting data only when convenient for the facility''s case mix index');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88ef7bd2-479d-441c-b0bd-022c29981989', '8a009f7e-1654-4434-8f36-732bb7c55f89', 3, 'Ignoring UHDDS for any non-Medicare patient');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee9f495f-a8e3-4e09-bd46-dd6612e9b9ed', '86c28deb-1c37-4bc5-880f-0af35ea1a614', 0, 'Coding staff having full, unrestricted access to every patient''s entire longitudinal record across the health system regardless of job function');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8177598-676f-4418-a9fa-6f063a0ce834', '86c28deb-1c37-4bc5-880f-0af35ea1a614', 1, 'Limiting coder access to only the PHI reasonably necessary to perform coding-related job functions for the specific encounters they are assigned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad6a8c5a-bf08-4b06-8ada-35eea41b8496', '86c28deb-1c37-4bc5-880f-0af35ea1a614', 2, 'Sharing PHI freely among all hospital departments regardless of need');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21b68edf-0f48-4a7b-8c40-36b3628f1b79', '86c28deb-1c37-4bc5-880f-0af35ea1a614', 3, 'Applying ''minimum necessary'' only to external requests, never to internal staff access');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6354367d-b155-45e7-800e-9fb029d02a97', 'de246ceb-ea06-4a04-b715-0f84789452a7', 0, 'The False Claims Act, which imposes liability for knowingly submitting false or fraudulent claims for payment to federal healthcare programs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('152ace2a-2351-4726-8398-4faa3b170e4b', 'de246ceb-ea06-4a04-b715-0f84789452a7', 1, 'The Family and Medical Leave Act');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ffe84ea-5955-4f8b-8fbb-d3682564ad74', 'de246ceb-ea06-4a04-b715-0f84789452a7', 2, 'The Fair Labor Standards Act');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ebfbd26-4a46-45ed-ad3c-a0045a741fae', 'de246ceb-ea06-4a04-b715-0f84789452a7', 3, 'The Americans with Disabilities Act');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6bf2c82-60d9-4b4d-b720-e1929f58ae42', '7454fd88-0b4f-4c70-888a-5be09f0a1485', 0, 'Only the billing summary is complete; underlying clinical documentation completeness is irrelevant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc68e557-03bb-40eb-86ae-61d06f0021ab', '7454fd88-0b4f-4c70-888a-5be09f0a1485', 1, 'Required elements (authentication/signatures, timely documentation, consistent clinical detail supporting coded diagnoses/procedures) are present, consistent with both accreditation/regulatory standards and internal HIM policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('804c1b4a-1a89-4714-b21e-edd72ef0495c', '7454fd88-0b4f-4c70-888a-5be09f0a1485', 2, 'Records are considered complete once discharged, regardless of missing signatures or dictation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2740296c-f2a8-44be-94ff-77e544690b8f', '7454fd88-0b4f-4c70-888a-5be09f0a1485', 3, 'Completeness only matters for Medicare patients');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0759042d-c9f5-4a13-a8eb-21fc5ae3cff7', 'a0af236a-f28e-42ee-bc74-df9a49a93859', 0, 'It repealed the HIPAA Privacy and Security Rules entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a168bfe7-7f82-4611-905c-7fd623ebc438', 'a0af236a-f28e-42ee-bc74-df9a49a93859', 1, 'It strengthened HIPAA enforcement (including breach notification requirements) and promoted the adoption and meaningful use of electronic health records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('426f4f44-4a27-446f-b84c-9057bb528b72', 'a0af236a-f28e-42ee-bc74-df9a49a93859', 2, 'It applies only to paper-based health records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f52aac93-a4c0-42b7-b648-efe2671326fb', 'a0af236a-f28e-42ee-bc74-df9a49a93859', 3, 'It solely governs Medicare reimbursement rates');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1cba68c6-fe84-4322-ab06-8bb9258fa89f', '73bc9669-79fe-48a9-8b00-e2a8cf6df046', 0, 'Notify affected individuals only if the breach involves more than 10,000 records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e78b4ddf-8897-4cd5-9657-7d79b83d5967', '73bc9669-79fe-48a9-8b00-e2a8cf6df046', 1, 'Notify affected individuals (and, depending on breach size, HHS and potentially media) within specified timeframes following discovery of the breach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31326b07-2986-4f76-8d39-ac99fbf411db', '73bc9669-79fe-48a9-8b00-e2a8cf6df046', 2, 'Never notify anyone, to avoid reputational harm');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1d10221-55a7-4d31-ade1-d9ef3f9b07a2', '73bc9669-79fe-48a9-8b00-e2a8cf6df046', 3, 'Wait until the next annual compliance audit to disclose the breach');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('736d00a1-d2d8-4a4e-bd70-4d597ea5f582', 'a3a94e71-9233-4dd2-88de-f91ca70fca15', 0, 'Always follow the payer''s guideline over the Official Guidelines, since payers control reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1220519e-15c1-4e55-819d-9a26eaa66589', 'a3a94e71-9233-4dd2-88de-f91ca70fca15', 1, 'Apply correct, compliant coding per the Official Guidelines as the baseline, and address payer-specific requirements (e.g., additional documentation, modifier use) through compliant means — not by assigning a code known to be clinically/technically inaccurate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff397c2c-42a6-43ff-82fe-fc75d78292ed', 'a3a94e71-9233-4dd2-88de-f91ca70fca15', 2, 'Refuse to bill that payer at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fb0449c-2aff-4e89-a208-2424a482af3e', 'a3a94e71-9233-4dd2-88de-f91ca70fca15', 3, 'Assign both codes on the same claim regardless of payer edits');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('842fb5ad-24c9-4936-8846-5b1d01e5acc7', '5d2d5446-7753-4cc0-99fa-b566504f012d', 0, 'Increase reimbursement for facilities regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6c269b9-419a-461f-ac92-335040efeaf5', '5d2d5446-7753-4cc0-99fa-b566504f012d', 1, 'Prevent improper payment for code pairs that should not be reported together for the same patient on the same date of service (e.g., unbundling a comprehensive procedure into its component parts), promoting correct coding and reducing improper Medicare payments');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f2a7dee-bb93-4100-b8dd-b134061827b7', '5d2d5446-7753-4cc0-99fa-b566504f012d', 2, 'Replace the need for ICD-10-CM diagnosis coding entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae9b9a5f-f699-487f-86f4-6f7fdcd15607', '5d2d5446-7753-4cc0-99fa-b566504f012d', 3, 'Apply only to inpatient hospital claims');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('975d9d23-3ff8-4988-930a-b06f2218bf02', 'efbdc7f2-253c-4ced-9682-6ee6d7925124', 0, 'Coders may construct queries however they wish, since ethical standards don''t address query practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b96daf9b-1b58-4276-a4d0-59496d3f07f3', 'efbdc7f2-253c-4ced-9682-6ee6d7925124', 1, 'Coders should only query when a diagnosis affects reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d242346-08d5-468f-a79a-b39b482c3583', 'efbdc7f2-253c-4ced-9682-6ee6d7925124', 2, 'Coders are expected to query a provider for clarification when documentation is ambiguous, conflicting, or incomplete, rather than assigning a code based on assumption — consistent with the broader ethical duty to code accurately and completely based on the health record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3dc693e8-d781-4994-8f5d-2a7a898ddde8', 'efbdc7f2-253c-4ced-9682-6ee6d7925124', 3, 'Coders should never query, deferring entirely to CDI staff');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f1120ad-ccf9-4656-b39e-8e8cda72d302', '3fb22086-c3ed-42b5-bacd-4ec84f8d56dd', 0, 'Replace the need for coder training entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4683c296-f011-426e-9036-f745ed376047', '3fb22086-c3ed-42b5-bacd-4ec84f8d56dd', 1, 'Periodically review coded claims/records for accuracy and guideline adherence, identifying patterns of error (e.g., systemic upcoding, undercoding, or POA misassignment) before they result in larger compliance exposure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea6fa861-4993-4221-8375-e2b774829929', '3fb22086-c3ed-42b5-bacd-4ec84f8d56dd', 2, 'Only occur once, at the time an employee is hired');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29bde016-a7a0-4f01-aad4-c36208f1f47b', '3fb22086-c3ed-42b5-bacd-4ec84f8d56dd', 3, 'Apply exclusively to outpatient claims');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07fad610-fe23-46dd-9d7d-24d889a78c88', 'a8d0489e-9ca8-4f10-a80e-43f49b750604', 0, 'Only literal, deliberate intent to defraud qualifies as ''knowing'' — good-faith mistakes can never create liability under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2853167-4477-4f14-89d8-4aaa89d89585', 'a8d0489e-9ca8-4f10-a80e-43f49b750604', 1, '''Knowingly'' can include actual knowledge, deliberate ignorance, or reckless disregard of the truth or falsity of the claim — meaning a pattern of reckless, unverified coding practices can create exposure even without provable deliberate intent to defraud');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d18b1a38-3b93-4981-8cec-e6fb9a0f7291', 'a8d0489e-9ca8-4f10-a80e-43f49b750604', 2, 'The False Claims Act applies only to physicians, never to coders or facilities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a6e3a02-e047-4dc1-ab20-aa538fdd6ce4', 'a8d0489e-9ca8-4f10-a80e-43f49b750604', 3, 'Liability requires a signed confession from the coder involved');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fc0d02f-de5e-48eb-80ce-421be8cc419f', '43009811-d6b9-4e11-946e-4fe4fc080031', 0, 'They are always identical documents with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2762ff69-cfdc-4b2e-abb6-d1ae4867d806', '43009811-d6b9-4e11-946e-4fe4fc080031', 1, 'AHIMA''s standards establish a professional ethical baseline expected of credentialed coders (like the CCS), while a facility''s internal policy operationalizes compliance requirements specific to that organization — a coder is expected to meet both, and internal policy should not conflict with the ethical baseline');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab3fd758-1706-455a-934e-d8d0c10c01b7', '43009811-d6b9-4e11-946e-4fe4fc080031', 2, 'Internal facility policy always overrides AHIMA''s ethical standards when the two conflict');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d82230c-f729-417f-87cc-83ae8e0beaa5', '43009811-d6b9-4e11-946e-4fe4fc080031', 3, 'AHIMA''s standards apply only to AHIMA staff, not credential holders working at hospitals');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25760df3-7c68-4a38-9d79-c6b8ae001e03', '8f685530-81b3-4c46-bc32-ecdff3ca11eb', 0, 'A locked server room door');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5cefffc8-5259-499b-a063-290e0452af98', '8f685530-81b3-4c46-bc32-ecdff3ca11eb', 1, 'A firewall configuration on the hospital network');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('630975ee-c8e5-4410-aed1-db2d94a7bd98', '8f685530-81b3-4c46-bc32-ecdff3ca11eb', 2, 'A documented security risk assessment process and workforce security-training policy governing who may access ePHI systems and under what conditions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f9df2a96-017d-4707-8298-39ce2d906108', '8f685530-81b3-4c46-bc32-ecdff3ca11eb', 3, 'An encrypted hard drive');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef6bdf86-113e-4479-8168-2631bdaf1658', '8baa0422-32f6-4d70-92a6-be844f408f37', 0, 'No action, since errors are considered a normal and acceptable part of coding operations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79f94644-9cc6-4737-8746-7c027aed53f8', '8baa0422-32f6-4d70-92a6-be844f408f37', 1, 'Targeted staff education/retraining on the specific identified error pattern, and, where required, correction/resubmission of affected claims consistent with applicable payer and regulatory requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ca15773-a3a3-47d7-bd01-b0a2242f6161', '8baa0422-32f6-4d70-92a6-be844f408f37', 2, 'Termination of the entire coding department without further investigation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d0c2654f-0596-4d25-878c-d2943d14a8c7', '8baa0422-32f6-4d70-92a6-be844f408f37', 3, 'Ignoring the pattern unless a payer specifically flags it first');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08b5e468-013a-49b8-85b6-30a225115821', 'b7d17a91-65a8-4923-bf33-c484cbce627e', 0, 'A procedure or service is supported by a diagnosis code that justifies it as reasonable and necessary under applicable payer coverage policy — mismatched diagnosis/procedure pairings can result in denied claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6023bcf3-26cf-4e55-8f98-c6db026d275b', 'b7d17a91-65a8-4923-bf33-c484cbce627e', 1, 'Every claim automatically qualifies for the highest available reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97e00f71-5247-470c-aa3f-800380b0ff7a', 'b7d17a91-65a8-4923-bf33-c484cbce627e', 2, 'Medical necessity applies only to inpatient claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dccaea45-6ad8-4609-b48b-3c9bdf3d7762', 'b7d17a91-65a8-4923-bf33-c484cbce627e', 3, 'Diagnosis codes are irrelevant to medical necessity determinations');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c99d772a-22a6-49c9-8b37-780fd9c55e03', 'b5f41433-807e-4a7b-b424-4339c3fadfb0', 0, 'An EHR is designed to be shared across and interoperable with other healthcare organizations, going beyond a single practice''s internal digital chart (the traditional EMR concept)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('160cd991-568f-443b-95cf-1df6a7bf47ec', 'b5f41433-807e-4a7b-b424-4339c3fadfb0', 1, 'An EMR contains imaging data while an EHR never does');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7aff4b0-442c-44b7-8a84-9efd66fe28ad', 'b5f41433-807e-4a7b-b424-4339c3fadfb0', 2, 'There is no meaningful distinction between the two terms');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69f0fbae-2f7b-4ebd-a046-7aece37d3201', 'b5f41433-807e-4a7b-b424-4339c3fadfb0', 3, 'An EHR is always paper-based while an EMR is always electronic');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4b5a95e-e91f-4714-86a4-4fe4bd2328d5', 'd046833c-2598-45fc-be7e-b07b72f9720c', 0, 'Replace the need for any coder judgment entirely, assigning all codes automatically with no human review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1754ba5-c5d3-48c1-bde5-940f0decaeb6', 'd046833c-2598-45fc-be7e-b07b72f9720c', 1, 'Assist coders in identifying and sequencing correct codes through logic-based prompts, code lookups, and edits, while still relying on coder expertise and documentation review for accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71f7d473-e6b8-467a-9870-d49393a815fe', 'd046833c-2598-45fc-be7e-b07b72f9720c', 2, 'Only generate patient billing statements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0541a1f-6994-4b03-a83e-c396e811507c', 'd046833c-2598-45fc-be7e-b07b72f9720c', 3, 'Manage hospital staff scheduling');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e98ea30b-a70a-41e2-8719-f6994a1c0b39', '3e746a12-638a-47df-9e30-0add7ccd215f', 0, 'Translate ICD-10-CM/PCS codes and other case data into the appropriate MS-DRG (or other DRG system) for reimbursement/severity classification purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ddb27475-7bee-42f1-983e-0c0074fead2b', '3e746a12-638a-47df-9e30-0add7ccd215f', 1, 'Convert paper records into electronic format');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e81bd0f-7fc5-4b04-97a0-00b6ba57056d', '3e746a12-638a-47df-9e30-0add7ccd215f', 2, 'Generate patient appointment reminders');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17afa3f7-aa45-405a-bbda-4d17dfc8aa62', '3e746a12-638a-47df-9e30-0add7ccd215f', 3, 'Perform real-time clinical decision support during a patient encounter');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e58d161-6e86-4be5-9a29-8972bd1ed0fb', '50c1681b-0ee1-4d83-8adc-aea5f3745f10', 0, 'Fully replaces human coders with no oversight required');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('112752df-855b-42f2-b220-be18fd9cabb7', '50c1681b-0ee1-4d83-8adc-aea5f3745f10', 1, 'Uses natural language processing (NLP) or structured data to suggest candidate codes from clinical documentation, which a credentialed coder then reviews, validates, and finalizes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a663c01c-d89f-4290-a5e5-a249585c9938', '50c1681b-0ee1-4d83-8adc-aea5f3745f10', 2, 'Is used exclusively for scheduling, not coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f861fb74-a129-4d57-8850-cea92d9f5cfb', '50c1681b-0ee1-4d83-8adc-aea5f3745f10', 3, 'Automatically submits claims to payers with no human review step');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d09c331-4cea-4749-837c-fcfababa6327', 'bddf2ea6-2745-471d-849d-ce6276b33aee', 0, 'CAC software has no known risks or limitations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c27b470d-e36e-473a-b8e1-2fe50ab1a26d', 'bddf2ea6-2745-471d-849d-ce6276b33aee', 1, 'CAC may suggest a code based on documentation language pattern-matching alone, without capturing full clinical context, POA status, or guideline nuance — risking inaccurate code assignment if not properly validated by a coder');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f67d103d-98ea-4a31-97f4-6a618d20829c', 'bddf2ea6-2745-471d-849d-ce6276b33aee', 2, 'CAC always produces more accurate codes than a human coder in every scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4923d13d-21f0-4b45-a23a-127331eedbbb', 'bddf2ea6-2745-471d-849d-ce6276b33aee', 3, 'CAC cannot be used with ICD-10-CM/PCS at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be4d0d5b-06ee-4afb-b62a-1e37202986e5', '34c12f21-02b9-4a06-919a-4b27b8fb3a66', 0, 'HITECH requirements are irrelevant to encoder/grouper/CAC systems');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3647f93a-1dd1-413e-8164-77ac6201aa48', '34c12f21-02b9-4a06-919a-4b27b8fb3a66', 1, 'Systems handling ePHI (including coding/abstracting systems) must operate consistent with HIPAA Security Rule safeguards as reinforced by HITECH, including appropriate access controls and audit trails');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8cdfdada-ad83-47c2-9e31-6eb30d877fa9', '34c12f21-02b9-4a06-919a-4b27b8fb3a66', 2, 'HITECH only applies to insurance companies, never to hospital HIM departments');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76cf0363-0348-4239-9e7c-da7dc8d7f5b9', '34c12f21-02b9-4a06-919a-4b27b8fb3a66', 3, 'HITECH eliminated the need for EHR security safeguards');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
