INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27db91f8-68a8-4a52-a6c7-6f32066b978f', '6850f5a0-b310-4577-bbb9-7a5168b04692', 0, 'A brand-new EHR system with no historical data');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ae68f37-8342-4f3c-9d2b-55df7fa4de54', '6850f5a0-b310-4577-bbb9-7a5168b04692', 1, 'Difficulty exchanging or migrating data between an older health information system and newer platforms due to differing data standards, formats, or structures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a1ec559-cbbf-415b-a1e6-cfc901a9289b', '6850f5a0-b310-4577-bbb9-7a5168b04692', 2, 'A system used only for scheduling appointments');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('afc683ff-b844-45cb-a722-18dd1f9b5246', '6850f5a0-b310-4577-bbb9-7a5168b04692', 3, 'A system that has no electronic components at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
