INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ceded9c2-6724-403e-a20e-e4f05ab54027', '59a9b167-2b5a-458a-b532-18b24bd8f876', 0, 'Accept every system-suggested code without independent verification against the source documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccc0908e-4f2d-477d-a95e-56186a8f3350', '59a9b167-2b5a-458a-b532-18b24bd8f876', 1, 'Independently verify that system-suggested codes are actually supported by, and consistent with, the documentation and applicable coding guidelines before finalizing them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8083d490-1470-4e36-9451-4cdb03ab7793', '59a9b167-2b5a-458a-b532-18b24bd8f876', 2, 'Disable all software assistance and code entirely without any technology tools');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab19c922-6b6f-4879-ba8c-9461fa9984c0', '59a9b167-2b5a-458a-b532-18b24bd8f876', 3, 'Only verify codes that affect reimbursement, ignoring all others');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
