INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4eca0007-5546-4bf6-a57b-04a016a325ee', '7309e031-c940-45b7-b702-6f30f9f1b23e', 0, 'The ability of different information systems, devices, or applications to access, exchange, and cooperatively use data in a coordinated manner');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('881f2be6-580c-4263-8248-6b27908a2c50', '7309e031-c940-45b7-b702-6f30f9f1b23e', 1, 'The physical durability of computer hardware');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('584aa6f1-56b0-4fc3-9a0e-45e652f88923', '7309e031-c940-45b7-b702-6f30f9f1b23e', 2, 'A single vendor''s product line compatibility with itself only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49f9d31e-3717-4b72-8a63-758228aa60be', '7309e031-c940-45b7-b702-6f30f9f1b23e', 3, 'The speed at which a single system processes a query');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
