INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ab16a2d-2ca1-45a2-a427-be5fbbb4a113', '91e0d7a8-94ec-42b0-8a03-a36aa5610a86', 0, 'A coder assigns codes based on documentation review and coding guidelines, uses the encoder to assist with code lookup/sequencing logic, and the grouper then calculates the resulting DRG from those finalized, documentation-supported codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4edff425-ce10-4cb6-84c6-403843d41c34', '91e0d7a8-94ec-42b0-8a03-a36aa5610a86', 1, 'A coder lets the grouper software choose which diagnoses to add to the record purely to reach a higher-weighted DRG, regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c09d021-7f4d-4845-9842-db026e2d6761', '91e0d7a8-94ec-42b0-8a03-a36aa5610a86', 2, 'A facility bypasses coder review entirely, submitting whatever DRG the grouper outputs from raw, unverified data');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8055efdd-f85e-4462-b3e5-fccf5f180e0e', '91e0d7a8-94ec-42b0-8a03-a36aa5610a86', 3, 'The grouper software is used only after claims have already been submitted to payers');
